CREATE TABLE IF NOT EXISTS "acc_project_deliverable" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "project_id" bigint NOT NULL,
    "template_requirement_key" varchar(128),
    "source_template_revision_id" bigint,
    "applicable_stage_code" varchar(32),
    "required_flag" tinyint NOT NULL DEFAULT 0,
    "template_id" bigint,
    "code" varchar(64) NOT NULL,
    "name" varchar(255) NOT NULL,
    "acceptance_id" bigint,
    "deliverable_type" varchar(32) NOT NULL DEFAULT 'REQUIRED',
    "deliverable_url" varchar(500),
    "check_user_id" bigint,
    "check_time" timestamp,
    "check_result" text,
    "status" varchar(32) NOT NULL DEFAULT 'PENDING',
    "remark" varchar(500),
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" tinyint NOT NULL DEFAULT 0,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_acc_project_deliverable_requirement"
        UNIQUE ("tenant_id", "project_id", "source_template_revision_id", "template_requirement_key"),
    CONSTRAINT "uk_pms_acc_deliverable_checklist_code" UNIQUE ("project_id", "code"),
    CONSTRAINT "chk_test_injected_mapper_failure" CHECK ("template_requirement_key" <> 'FAIL')
);
